nodes.exampleSchema:
Schema.Struct({
  voucherId: PersonId,
  personId: PersonId,
  reason: Schema.NonEmptyString,
  vouchedAt: Schema.DateTimeUtcFromString,
})

Schema.Record(
  PersonId,
  Schema.TaggedUnion({
    UNVOUCHED: {},
    VOUCHED: {
      vouches: Schema.NonEmptyArray(
        Schema.Struct({
          voucherId: PersonId,
          reason: Schema.NonEmptyString,
          vouchedAt: Schema.DateTimeUtcFromString,
        }),
      ),
    },
    BLOCKED: {
      reason: Schema.NonEmptyString,
      decidedByPersonId: PersonId,
      decidedAt: Schema.DateTimeUtcFromString,
    },
  }),
)

Schema.Record(
  PersonId,
  Schema.Array(
    Schema.Struct({
      personId: PersonId,
      vouchedAt: Schema.DateTimeUtcFromString,
    }),
  ),
)

Schema.Record(
  PersonId,
  Schema.NonEmptyArray(
    Schema.Struct({
      reportId: Schema.NonEmptyString.pipe(Schema.brand("PersonReportId")),
      reason: Schema.Literals(["AUTOMATED", "IMPERSONATION", "SPAM", "ABUSIVE"]),
      reporterId: PersonId,
      reportedAt: Schema.DateTimeUtcFromString,
    }),
  ),
)

Schema.Record(
  PersonId,
  Schema.Struct({
    vouched: Schema.Int,
    blocked: Schema.Array(PersonId),
    revoked: Schema.Array(PersonId),
    withUpheldConductVerdicts: Schema.Array(PersonId),
  }),
)
